def apply(t,put,ok):
    for i,(n,old,new) in UNITS.items():
        ok(t['Units'][i].get('Cost')==old,f'{n} [{i}] base price {old}');put('Units',i,{'Cost':new});ok(t['Units'][i]['Cost']==new,f'{n} base now {new}')
    for i,(u,n,old,new) in OPTIONS.items():
        ok((t['OptionsJson'][i].get('Cost') or 0)==old,f'{u}: {n} [{i}] price {old}');put('OptionsJson',i,{'Cost':new});ok(t['OptionsJson'][i]['Cost']==new,f'{n} now {new}')
    return {'units':len(UNITS),'options':len(OPTIONS)}
